def give_groups_an_owner(apps, schema_editor):
    """Existing groups: the creator becomes owner if still in the group,
    otherwise the longest-standing admin, otherwise the longest-standing member."""
    Conversation = apps.get_model('chat', 'Conversation')
    Participant = apps.get_model('chat', 'Participant')
    for conversation in Conversation.objects.filter(kind='group'):
        active = Participant.objects.filter(conversation=conversation, left_at__isnull=True)
        if active.filter(role='owner').exists():
            continue
        owner = (
            active.filter(user_id=conversation.created_by_id, pending=False).first()
            or active.filter(role='admin').order_by('joined_at').first()
            or active.filter(pending=False).order_by('joined_at').first()
        )
        if owner is not None:
            Participant.objects.filter(pk=owner.pk).update(role='owner')


